create or replace function public.is_approved_school_member(target_school_id uuid) returns boolean language sql stable security definer set search_path = public as $$
  select exists (
    select 1
    from public.school_memberships membership
    join public.schools school on school.id = membership.school_id
    where membership.school_id = target_school_id
      and membership.user_id = auth.uid()
      and school.approval_status = 'approved'
  );
$$;

revoke execute on function public.is_approved_school_member(uuid) from public, anon;
grant execute on function public.is_approved_school_member(uuid) to authenticated;

drop policy if exists academic_years_member_access on public.academic_years;
drop policy if exists classes_member_access on public.classes;
drop policy if exists students_member_access on public.students;
drop policy if exists enrollments_member_access on public.student_enrollments;
drop policy if exists media_assets_member_access on public.media_assets;
