drop policy if exists subjects_member_access on public.subjects;
drop policy if exists assessments_member_access on public.assessments;
drop policy if exists grades_member_access on public.grades;
drop policy if exists payments_member_access on public.payments;
drop policy if exists documents_member_access on public.school_documents;
drop policy if exists calendar_member_access on public.calendar_events;

create policy academic_years_approved_member_access on public.academic_years for all to authenticated using (public.is_approved_school_member(school_id)) with check (public.is_approved_school_member(school_id));
